use std::{env,fs::File,io::{Read,BufReader}};
fn main(){let a:Vec<String>=env::args().collect();if a.len()<2||a[1]=="--help"{println!("Usage: fnv64 FILE  # fast non-cryptographic FNV-1a checksum");std::process::exit(if a.len()<2{2}else{0});}let f=File::open(&a[1]).unwrap_or_else(|e|{eprintln!("{}",e);std::process::exit(2)});let mut r=BufReader::new(f);let mut h:u64=0xcbf29ce484222325;let mut n:u64=0;let mut b=[0u8;65536];loop{let z=r.read(&mut b).unwrap();if z==0{break}for x in &b[..z]{h^=*x as u64;h=h.wrapping_mul(0x100000001b3);}n+=z as u64;}println!("fnv1a64={:016x}\nbytes={}",h,n);}
